int ways(int coins[], int count, int amount)
{
    // Guard against null pointer or invalid count.
    if (!coins || count <= 0) return 0;

    // Memoization table: dp[i][j] stores the number of ways to make j with the first i coins.
    std::vector<std::vector<int>> dp(count + 1, std::vector<int>(amount + 1, 0));

    // Fill the table using the original recursive logic.
    for (int i = 1; i <= count; ++i) {
        for (int j = 0; j <= amount; ++j) {
            if (j == 0) {
                dp[i][j] = 1; // Only one way to make amount 0.
            } else if (j < coins[i - 1]) {
                dp[i][j] = dp[i - 1][j]; // Cannot use coin i.
            } else {
                dp[i][j] = dp[i - 1][j] + dp[i][j - coins[i - 1]]; // Use coin i or skip it.
            }
        }
    }

    return dp[count][amount];
}

int ways(int coins[], int count, int amount)
{
    // Base case: exact amount achieved.
    if (amount == 0)
        return 1;

    // No coins left or insufficient amount → no solution.
    if (amount < 0 || count == 0)
        return 0;

    // Use a loop to avoid deep recursion and keep the same result.
    int result = 0;
    for (int i = 0; i < count; ++i) {
        // Skip the current coin if it is larger than the remaining amount.
        if (coins[i] > amount)
            continue;
        // Recurse with one fewer coin and the reduced amount.
        result += ways(coins, count - 1, amount - coins[i]);
    }
    return result;
}

long long fact(int n)
{
    // Base case: factorial of 0 or 1 is 1.
    if (n <= 1)
        return 1;

    // Recursive call; assumes n is non‑negative.
    return n * fact(n - 1);
}

