int total(const int arr[], int n)
{
    // Guard against null pointer or non‑positive length.
    if (arr == nullptr || n <= 0) {
        return 0;
    }

    // Use a local variable for clarity and to avoid modifying the caller's array.
    const int* p = arr;
    int sum = 0;

    // Iterate from the last element to the first.
    for (int i = n; i > 0; --i) {
        sum += p[i - 1];
    }

    return sum;
}

